import { test, expect } from '@playwright/test';

test.describe('Notification Bell Badge Count', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should display badge count when notifications exist', async ({ page }) => {
    // Intercept the API call to mock notifications
    await page.route('**/api/notifications', (route) => {
      route.continue();
    });

    // Mock the response with 3 notifications
    await page.route('**/api/notifications', (route) => {
      route.abort();
      route.continue({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({
          notifications: [
            { id: 1, message: 'New message', read: false },
            { id: 2, message: 'System update', read: false },
            { id: 3, message: 'Comment reply', read: false },
          ],
          count: 3,
        }),
      });
    });

    // Wait for the notifications to load
    await page.waitForLoadState('networkidle');

    // Verify the notification bell icon is visible
    const notificationBell = page.getByRole('button', { name: /notifications/i });
    await expect(notificationBell).toBeVisible();

    // Verify the badge count is displayed
    const badge = page.getByText('3');
    await expect(badge).toBeVisible();

    // Verify the badge has the correct styling (e.g., red background)
    await expect(badge).toHaveCSS('background-color', 'rgb(255, 0, 0)');

    // Verify the badge is positioned correctly on the icon
    const badgeBoundingBox = await badge.boundingBox();
    const bellBoundingBox = await notificationBell.boundingBox();
    expect(badgeBoundingBox.x).toBeGreaterThan(bellBoundingBox.x);
    expect(badgeBoundingBox.y).toBeGreaterThan(bellBoundingBox.y);
  });

  test('should not display badge when no notifications exist', async ({ page }) => {
    // Intercept the API call to mock no notifications
    await page.route('**/api/notifications', (route) => {
      route.abort();
      route.continue({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({
          notifications: [],
          count: 0,
        }),
      });
    });

    // Wait for the notifications to load
    await page.waitForLoadState('networkidle');

    // Verify the notification bell icon is visible
    const notificationBell = page.getByRole('button', { name: /notifications/i });
    await expect(notificationBell).toBeVisible();

    // Verify the badge does not exist
    const badge = page.getByText('0');
    await expect(badge).not.toBeVisible();

    // Verify the badge element is not present in the DOM
    const badgeElement = page.locator('[data-testid="notification-badge"]');
    await expect(badgeElement).not.toBeVisible();

    // Verify the notification bell has no badge styling
    await expect(notificationBell).not.toHaveCSS('background-color', 'rgb(255, 0, 0)');
  });
});
